"""Explicit comparison of saved synthetic purchases, with frozen history."""
CSS='''
#purchase-comparison{font-family:Arial,sans-serif;overflow-wrap:anywhere}
#purchase-comparison .comparison-fields{display:grid;grid-template-columns:1fr;gap:0 12px}
.po-negotiation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:16px 0}.po-negotiation-grid>section{min-width:0;border:1px solid #c4d6ee;border-radius:9px;padding:14px;background:#f6f9ff}.po-negotiation-grid h3{font-size:14px;font-weight:800}.po-negotiation-grid label{font-size:12px}.po-negotiation-grid dd{margin:4px 0 15px;font-weight:700}.po-negotiation-grid dt{font-size:12px;color:#4a6280}@media(max-width:1100px){.po-negotiation-grid{grid-template-columns:1fr}}
#purchase-comparison .comparison-fields label{min-width:0}
#purchase-comparison .comparison-check{display:flex;align-items:center;gap:10px;margin:16px 0}
#purchase-comparison input[type=checkbox]{display:inline-block;width:18px;min-width:18px;margin:0}
#purchase-comparison .comparison-quota{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px;align-items:end;margin:12px 0}
#purchase-comparison .comparison-quota label{margin:0}
#purchase-comparison .comparison-scroll{overflow-x:auto;max-width:100%;margin:14px 0;border:1px solid #b9cce6;border-radius:8px}
#purchase-comparison table{min-width:780px}
#purchase-comparison th{background:#e1effb;color:#183c68}
#purchase-comparison th,#purchase-comparison td{vertical-align:top}
#purchase-comparison .comparison-result{border:1px solid #b9cce6;background:#f3f8ff;border-radius:9px;padding:16px;margin-top:18px}
#purchase-comparison .comparison-result h3{margin-top:0;font-weight:700}
#purchase-comparison .comparison-status{white-space:pre-wrap;margin:12px 0;color:#173e76}
#purchase-comparison .comparison-quota button{margin:0}
@media(max-width:900px){#purchase-comparison .comparison-fields{grid-template-columns:1fr}#purchase-comparison .comparison-quota{grid-template-columns:1fr 1fr}}
'''
JS=r'''
let purchaseComparisonSequence=0;
function renderPurchaseComparisonSaved(proposal){
 let submitted=false;const sequence=++purchaseComparisonSequence,dataset=$('dataset').value;
 let box=$('purchase-comparison');if(!box){box=document.createElement('section');box.id='purchase-comparison';box.className='card';$('review-panel').append(box)}box.replaceChildren();
 const h=document.createElement('h2');h.textContent='COMPARAR CONDICIONES DE COMPRA';box.append(h);
 const note=document.createElement('p');note.textContent='Compara la misma cantidad y proveedor, con o sin déficit. Las referencias y aceptaciones declaradas quedan sin verificar. Guardar no modifica la propuesta original. La previsión compensa movimientos al cierre de cada día y no garantiza cobros, disponibilidad actual ni cobertura completa de obligaciones.';box.append(note);
 const panel=document.createElement('div');panel.className='comparison-fields';box.append(panel);const fields={};function input(key,label,type='text'){const l=document.createElement('label'),i=document.createElement('input');l.textContent=label;i.type=type;l.append(i);panel.append(l);fields[key]=i;return i}
 input('label','Nombre de la alternativa').value='Mi propuesta';input('actor','Responsable');
 input('price','Nuevo precio por unidad (opcional)','number').step='any';input('discount','Descuento porcentual alternativo (opcional)','number').step='any';input('due','Nuevo vencimiento de mercancía (opcional)','date');
 const originLabel=document.createElement('label');originLabel.textContent='Origen de las condiciones modificadas';const origin=document.createElement('select');for(const [v,t] of [['HYPOTHETICAL','Hipótesis para negociar'],['DOCUMENTED','Oferta documentada, sin verificar'],['UNCONFIRMED','Sin confirmar']]){const o=document.createElement('option');o.value=v;o.textContent=t;origin.append(o)}originLabel.append(origin);panel.append(originLabel);
 input('source','Referencia del soporte (obligatoria para oferta documentada)');

 const grid=document.createElement('div');grid.className='po-negotiation-grid';const original=document.createElement('section'),mine=document.createElement('section'),response=document.createElement('section');grid.append(original,mine,response);panel.before(grid);mine.append(panel);for(const [area,title,help] of [[original,'OFERTA ORIGINAL','Conservada. Los datos no se modifican.'],[mine,'MI PROPUESTA','Editable · Hipótesis o condición declarada.'],[response,'RESPUESTA DEL PROVEEDOR','Editable · Sin aceptación verificada.']]){const h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=help;area.prepend(h,p)}
 const terms=proposal.commercial_terms||{},list=document.createElement('dl');for(const [label,value] of [['Cantidad',stockNumber(proposal.quantity)+' '+proposal.unit],['Precio introducido',money(terms.entered_unit_price)+' euros'],['Descuento',terms.discount_mode==='PERCENT'?money(terms.discount_value)+' %':terms.discount_mode==='LINE_AMOUNT'?money(terms.discount_value)+' euros por línea':'Sin descuento'],['Precio neto por unidad',money(proposal.unit_price)+' euros'],['Vencimiento',stockDate(proposal.due_date)],['Total con IVA y portes',proposal.operation_total==null?'Portes pendientes':money(proposal.operation_total)+' euros']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;list.append(dt,dd)}original.append(list);
 const actorLabel=fields.actor.closest('label');grid.before(actorLabel);
 const responseEnabled=document.createElement('input');responseEnabled.type='checkbox';const responseCheck=document.createElement('label');responseCheck.className='comparison-check';responseCheck.append(responseEnabled,document.createTextNode(' Comparar respuesta recibida'));response.append(responseCheck);const responseFields={};for(const [key,label,type] of [['price','Precio de respuesta antes de descuentos','number'],['discount','Descuento de respuesta (%)','number'],['due','Vencimiento de respuesta','date'],['source','Referencia de la respuesta','text']]){const l=document.createElement('label'),i=document.createElement('input');l.textContent=label;i.type=type;if(type==='number'){i.step='any';i.min='0'}l.append(i);response.append(l);responseFields[key]=i;i.disabled=true}const responseOrigin=document.createElement('select'),responseOriginLabel=document.createElement('label');responseOriginLabel.textContent='Origen de la respuesta';for(const [v,t] of [['UNCONFIRMED','Sin confirmar'],['DOCUMENTED','Documentada, sin verificar']]){const o=document.createElement('option');o.value=v;o.textContent=t;responseOrigin.append(o)}responseOriginLabel.append(responseOrigin);response.append(responseOriginLabel);responseOrigin.disabled=true;responseEnabled.onchange=()=>{for(const i of Object.values(responseFields))i.disabled=!responseEnabled.checked;responseOrigin.disabled=!responseEnabled.checked};

 // Restore the pre-save alternatives for review without promoting their provenance.
 for(const saved of proposal.negotiation_at_save?.alternatives||[]){const t=saved.quote.commercial_terms,percent=t.discount_mode==='PERCENT'?t.discount_value:'0',price=t.discount_mode==='LINE_AMOUNT'?saved.quote.unit_price:t.entered_unit_price;if(saved.slot==='mine'){fields.price.value=price;fields.discount.value=percent;fields.due.value=saved.quote.due_date;origin.value=saved.condition.origin;fields.source.value=saved.condition.source_reference||''}else{responseEnabled.checked=true;responseEnabled.onchange();responseFields.price.value=price;responseFields.discount.value=percent;responseFields.due.value=saved.quote.due_date;responseOrigin.value=saved.condition.origin==='DOCUMENTED'?'DOCUMENTED':'UNCONFIRMED';responseFields.source.value=saved.condition.source_reference||''}}
 const quotaLabel=document.createElement('label'),quotaEnabled=document.createElement('input');quotaEnabled.type='checkbox';quotaLabel.className='comparison-check';quotaLabel.append(quotaEnabled,document.createTextNode(' Sustituir el calendario completo de cuotas de mi propuesta'));box.append(quotaLabel);const quotas=document.createElement('div');quotas.hidden=true;box.append(quotas);const addQuota=document.createElement('button');addQuota.type='button';addQuota.textContent='Añadir cuota';quotas.append(addQuota);const quotaRows=[];addQuota.onclick=()=>{const row=document.createElement('div'),component=document.createElement('select'),amount=document.createElement('input'),due=document.createElement('input'),remove=document.createElement('button');for(const [v,t] of [['MERCHANDISE','Mercancía'],['FREIGHT','Portes']]){const o=document.createElement('option');o.value=v;o.textContent=t;component.append(o)}amount.type='number';amount.step='0.01';amount.min='0.01';amount.setAttribute('aria-label','Importe de cuota con IVA');due.type='date';due.setAttribute('aria-label','Vencimiento de cuota');remove.type='button';remove.textContent='Eliminar cuota';row.className='comparison-quota';for(const [text,control] of [['Concepto',component],['Importe con IVA',amount],['Vencimiento',due]]){const label=document.createElement('label');label.textContent=text;label.append(control);row.append(label)}row.append(remove);quotas.append(row);const item={row,component,amount,due};quotaRows.push(item);remove.onclick=()=>{quotaRows.splice(quotaRows.indexOf(item),1);row.remove()}};quotaEnabled.onchange=()=>{quotas.hidden=!quotaEnabled.checked};
 const button=document.createElement('button');button.type='button';button.textContent='Comparar y conservar estudio';box.append(button);
 const status=document.createElement('p');status.className='comparison-status';status.setAttribute('role','status');box.append(status);const output=document.createElement('div');output.setAttribute('aria-live','polite');box.append(output);
 function render(items){output.replaceChildren();for(const item of items){const r=item.record,title=document.createElement('h3');title.textContent=(item.stale?'HISTÓRICO DESACTUALIZADO · ':'ESTUDIO GUARDADO · ')+new Intl.DateTimeFormat('es-ES',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Madrid'}).format(new Date(r.created_at));const card=document.createElement('section');card.className='comparison-result';card.append(title);output.append(card);const table=document.createElement('table');const head=document.createElement('tr');for(const t of ['Condición','Total a pagar','Ahorro','Saldo mínimo','Falta para reserva','Fecha de saldo mínimo','Estado']){const th=document.createElement('th');th.textContent=t;head.append(th)}table.append(head);const rows=[{label:'Propuesta original',result:r.baseline,saving:'0'},...r.alternatives];for(const a of rows){const tr=document.createElement('tr'),v=a.result;for(const value of [a.label,v.total?money(v.total)+' EUR':'Pendiente',a.saving===null?'Pendiente':money(a.saving)+' EUR',v.scenario?money(v.scenario.minimum_balance)+' EUR':'Pendiente',v.scenario?money(v.scenario.deficit)+' EUR':'Pendiente',v.scenario?stockDate(v.scenario.minimum_date):'Pendiente',v.status==='PENDING'?v.message:v.status==='SHORTFALL'?'No respeta la reserva':'Respeta la reserva en el escenario']){const td=document.createElement('td');td.textContent=value;tr.append(td)}table.append(tr);if(a.conditions){const p=document.createElement('p');p.textContent=Object.entries(a.conditions).map(([k,c])=>({unit_price:'Precio por unidad',pricing_mode:'Modalidad de precio',discount_mode:'Modalidad de descuento',discount_value:'Descuento',due_date:'Vencimiento de mercancía',shipping_due_date:'Vencimiento de portes',payment_installments:'Calendario de cuotas'}[k]||'Condición')+': '+({DOCUMENTED:'Documentada, sin verificar',HYPOTHETICAL:'Hipótesis para negociar',UNCONFIRMED:'Sin confirmar'}[c.origin])+(c.source_reference?' · '+c.source_reference:'')+(c.validity_status==='EXPIRED_AT_COMPARISON'?' · VIGENCIA CADUCADA':'')).join('; ');card.append(p)}}const scroll=document.createElement('div');scroll.className='comparison-scroll';scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label','Comparación de condiciones. Desplaza horizontalmente para ver todas las columnas.');scroll.append(table);card.append(scroll);const hint=document.createElement('small');hint.textContent='Desplaza la tabla horizontalmente para consultar todas las columnas.';card.append(hint);for(const a of rows){if(a.result.payments){const p=document.createElement('p');p.textContent=a.label+' · Pagos: '+a.result.payments.map(i=>stockDate(i.due_date)+': '+money(i.amount)+' EUR').join('; ');card.append(p)}}const p=document.createElement('p');p.textContent='Sin ganadora automática. No acredita viabilidad final ni aceptación verificada. Identificador: '+r.comparison_id;card.append(p)}}
 button.onclick=async()=>{submitted=true;button.disabled=true;status.textContent='Calculando y guardando la comparación…';try{const patch={};if(fields.price.value!=='')patch.unit_price=fields.price.value;if(fields.discount.value!==''){if(fields.price.value==='')throw Error('Indica el precio antes de descuentos para comparar el descuento.');patch.pricing_mode='BEFORE_DISCOUNT';patch.discount_mode='PERCENT';patch.discount_value=fields.discount.value}if(fields.due.value)patch.due_date=fields.due.value;if(quotaEnabled.checked)patch.payment_installments=quotaRows.map(i=>({component:i.component.value,amount:i.amount.value,due_date:i.due.value}));if(!Object.keys(patch).length&&!responseEnabled.checked)throw Error('Introduce un precio o vencimiento alternativo. Si hay cuotas, el nuevo vencimiento debe ser coherente con su calendario completo.');const conditions=Object.fromEntries(Object.keys(patch).map(k=>[k,{origin:origin.value,acceptance:'PENDING',source_reference:fields.source.value||null}]));const alternatives=[];if(Object.keys(patch).length)alternatives.push({label:fields.label.value,patch,conditions});if(responseEnabled.checked){const p={};if(responseFields.price.value!==''){p.unit_price=responseFields.price.value;p.pricing_mode='BEFORE_DISCOUNT';p.discount_mode=responseFields.discount.value!==''?'PERCENT':'NONE';p.discount_value=responseFields.discount.value||null}else if(responseFields.discount.value!=='')throw Error('Indica el precio de respuesta antes de aplicar su descuento.');if(responseFields.due.value)p.due_date=responseFields.due.value;if(!Object.keys(p).length)throw Error('Introduce al menos una condición de la respuesta.');alternatives.push({label:'Respuesta del proveedor',patch:p,conditions:Object.fromEntries(Object.keys(p).map(k=>[k,{origin:responseOrigin.value,acceptance:'PENDING',source_reference:responseFields.source.value||null}]))})}const r=await api('/api/purchases/comparisons',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:proposal.proposal_id,documentary_context_fingerprint:state.documentary_context.fingerprint,actor:fields.actor.value,alternatives})});if(sequence!==purchaseComparisonSequence||dataset!==$('dataset').value)return;render([{record:r,stale:false}]);status.textContent='ESTUDIO GUARDADO. La propuesta original permanece intacta.'}catch(e){if(sequence===purchaseComparisonSequence)status.textContent=e.message}finally{button.disabled=false}};
 api('/api/purchases/comparisons/read',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:proposal.proposal_id})}).then(r=>{if(!submitted&&sequence===purchaseComparisonSequence&&dataset===$('dataset').value)render(r.comparisons)}).catch(e=>{if(sequence===purchaseComparisonSequence)status.textContent=e.message});
}
'''
